-- FARMA CAPITAL — catálogo bajo pedido 2026-09-17
-- Dermaexpress + Birdman (sin merch) + Ewafra/DIS (sin lab/controlados).
-- Promexsa solo como techo / foto / nombre. precio=0 → Cotizar.
-- Idempotente: no inserta si el EAN ya existe; no marca bajo_pedido si hay stock.
-- Fotos: espejar a catalogo-propia/ con scripts/espejar-imagenes-bajo-pedido.js
-- luego reescribir imagen_url a farmacapital.mx (este SQL usa origen si aún no hay propia).

begin;

do $$
begin
  if not exists (
    select 1 from information_schema.columns
     where table_schema = 'public' and table_name = 'productos' and column_name = 'bajo_pedido'
  ) then
    raise exception 'Primero corre sql/patch_bajo_pedido_20260916.sql';
  end if;
end
$$;

create temp table _fc_cat_bp (
  sku text not null,
  ean text,
  nombre text not null,
  marca text,
  presentacion text,
  categoria text not null,
  subcategoria text,
  tipo text not null,
  costo numeric(12,2),
  precio numeric(12,2) not null,
  imagen_url text,
  fuente text not null,
  sku_externo text,
  techo numeric(12,2),
  disponible boolean not null default true
) on commit drop;

